427	func (s *Store) getDeploymentIdentityProvider(uid string) *storepb.IdentityProvider {
428		s.deploymentConfigMu.RLock()
429		defer s.deploymentConfigMu.RUnlock()
430		return cloneIdentityProvider(s.deploymentConfig.identityProviders[uid])
431	}
432	
433	func (s *Store) listDeploymentIdentityProviders() []*storepb.IdentityProvider {
434		s.deploymentConfigMu.RLock()
435		defer s.deploymentConfigMu.RUnlock()
436		providers := make([]*storepb.IdentityProvider, 0, len(s.deploymentConfig.identityProviders))
437		for _, provider := range s.deploymentConfig.identityProviders {
438			providers = append(providers, cloneIdentityProvider(provider))
439		}
440		slices.SortFunc(providers, func(a, b *storepb.IdentityProvider) int { return strings.Compare(a.Uid, b.Uid) })
441		return providers
442	}
443	
444	func (s *Store) getDeploymentInstanceSetting(key storepb.InstanceSettingKey) *storepb.InstanceSetting {
445		s.deploymentConfigMu.RLock()
446		defer s.deploymentConfigMu.RUnlock()
447		return cloneInstanceSetting(s.deploymentConfig.instanceSettings[key])
448	}
449	
450	func cloneIdentityProvider(provider *storepb.IdentityProvider) *storepb.IdentityProvider {
451		if provider == nil {
452			return nil
453		}
454		cloned := &storepb.IdentityProvider{}
455		proto.Merge(cloned, provider)
456		return cloned
457	}
458	
459	func cloneInstanceSetting(setting *storepb.InstanceSetting) *storepb.InstanceSetting {
460		if setting == nil {
461			return nil
462		}
463		cloned := &storepb.InstanceSetting{}
464		proto.Merge(cloned, setting)
465		return cloned
466	}
