4	
5	import "api/v1/user_service.proto";
6	import "google/api/annotations.proto";
7	import "google/api/field_behavior.proto";
8	import "google/protobuf/empty.proto";
9	import "google/protobuf/timestamp.proto";
10	
11	option go_package = "gen/api/v1";
12	
13	service AuthService {
14	  // GetCurrentUser returns the authenticated user's information.
15	  // Validates the access token and returns user details.
16	  // Similar to OIDC's /userinfo endpoint.
17	  rpc GetCurrentUser(GetCurrentUserRequest) returns (GetCurrentUserResponse) {
18	    option (google.api.http) = {get: "/api/v1/auth/me"};
19	  }
20	
21	  // SignIn authenticates a user with credentials and returns tokens.
22	  // On success, returns an access token and sets a refresh token cookie.
23	  // Supports password-based and SSO authentication methods.
24	  rpc SignIn(SignInRequest) returns (SignInResponse) {
25	    option (google.api.http) = {
26	      post: "/api/v1/auth/signin"
27	      body: "*"
28	    };
29	  }
30	
31	  // SignOut terminates the user's authentication.
32	  // Revokes the refresh token and clears the authentication cookie.
33	  rpc SignOut(SignOutRequest) returns (google.protobuf.Empty) {
34	    option (google.api.http) = {post: "/api/v1/auth/signout"};
35	  }
36	
37	  // RefreshToken exchanges a valid refresh token for a new access token.
38	  // The refresh token is read from the HttpOnly cookie.
39	  // Returns a new short-lived access token.
40	  rpc RefreshToken(RefreshTokenRequest) returns (RefreshTokenResponse) {
41	    option (google.api.http) = {
42	      post: "/api/v1/auth/refresh"
43	      body: "*"
44	    };
45	  }
46	}
47	
48	message GetCurrentUserRequest {}
49	
50	message GetCurrentUserResponse {
51	  // The authenticated user's information.
52	  User user = 1;
53	}
54	
55	message SignInRequest {
56	  // Nested message for password-based authentication credentials.
57	  message PasswordCredentials {
58	    // The username to sign in with.
59	    string username = 1 [(google.api.field_behavior) = REQUIRED];
60	
61	    // The password to sign in with.
62	    string password = 2 [(google.api.field_behavior) = REQUIRED];
63	  }
64	
65	  // Nested message for SSO authentication credentials.
66	  message SSOCredentials {
67	    // The resource name of the SSO provider.
68	    // Format: identity-providers/{uid}
69	    string idp_name = 1 [(google.api.field_behavior) = REQUIRED];
70	
71	    // The authorization code from the SSO provider.
72	    string code = 2 [(google.api.field_behavior) = REQUIRED];
73	
74	    // The redirect URI used in the SSO flow.
75	    string redirect_uri = 3 [(google.api.field_behavior) = REQUIRED];
76	
77	    // The PKCE code verifier for enhanced security (RFC 7636).
78	    // Optional - enables PKCE flow protection against authorization code interception.
79	    string code_verifier = 4 [(google.api.field_behavior) = OPTIONAL];
80	  }
81	
82	  // Authentication credentials. Provide one method.
83	  oneof credentials {
84	    // Username and password authentication.
85	    PasswordCredentials password_credentials = 1;
86	
87	    // SSO provider authentication.
88	    SSOCredentials sso_credentials = 2;
89	  }
90	}
91	
92	message SignInResponse {
93	  // The authenticated user's information.
94	  User user = 1;
95	
96	  // The short-lived access token for API requests.
97	  // Store in memory only, not in localStorage.
98	  string access_token = 2;
99	
100	  // When the access token expires.
101	  // Client should call RefreshToken before this time.
102	  google.protobuf.Timestamp access_token_expires_at = 3;
103	}
104	
105	message SignOutRequest {}
106	
107	message RefreshTokenRequest {}
108	
109	message RefreshTokenResponse {
110	  // The new short-lived access token.
111	  string access_token = 1;
112	
113	  // When the access token expires.
114	  google.protobuf.Timestamp expires_at = 2;
115	}
