28	// GetNameParentTokens returns the tokens from a resource name.
29	func GetNameParentTokens(name string, tokenPrefixes ...string) ([]string, error) {
30		parts := strings.Split(name, "/")
31		if len(parts) != 2*len(tokenPrefixes) {
32			return nil, errors.Errorf("invalid request %q", name)
33		}
34	
35		var tokens []string
36		for i, tokenPrefix := range tokenPrefixes {
37			if fmt.Sprintf("%s/", parts[2*i]) != tokenPrefix {
38				return nil, errors.Errorf("invalid prefix %q in request %q", tokenPrefix, name)
39			}
40			if parts[2*i+1] == "" {
41				return nil, errors.Errorf("invalid request %q with empty prefix %q", name, tokenPrefix)
42			}
43			tokens = append(tokens, parts[2*i+1])
44		}
45		return tokens, nil
46	}
47	
48	func ExtractInstanceSettingKeyFromName(name string) (string, error) {
49		const prefix = "instance/settings/"
50		if !strings.HasPrefix(name, prefix) {
51			return "", errors.Errorf("invalid instance setting name: expected prefix %q, got %q", prefix, name)
52		}
53	
54		settingKey := strings.TrimPrefix(name, prefix)
55		if settingKey == "" {
56			return "", errors.Errorf("invalid instance setting name: empty setting key in %q", name)
57		}
58	
59		// Ensure there are no additional path segments
60		if strings.Contains(settingKey, "/") {
61			return "", errors.Errorf("invalid instance setting name: setting key cannot contain '/' in %q", name)
62		}
63	
64		return settingKey, nil
65	}
66	
67	// ExtractUserIDFromName returns the uid from a resource name.
68	func ExtractUserIDFromName(name string) (int32, error) {
69		tokens, err := GetNameParentTokens(name, UserNamePrefix)
70		if err != nil {
71			return 0, err
72		}
73		id, err := util.ConvertStringToInt32(tokens[0])
74		if err != nil {
75			return 0, errors.Errorf("invalid user ID %q", tokens[0])
76		}
77		return id, nil
78	}
79	
80	// ExtractMemoUIDFromName returns the memo UID from a resource name.
81	// e.g., "memos/uuid" -> "uuid".
82	func ExtractMemoUIDFromName(name string) (string, error) {
83		tokens, err := GetNameParentTokens(name, MemoNamePrefix)
84		if err != nil {
85			return "", err
86		}
87		id := tokens[0]
88		return id, nil
89	}
90	
91	// ExtractAttachmentUIDFromName returns the attachment UID from a resource name.
