137	// ValidateAndGenerateUID validates a user-provided UID or generates a new one.
138	// If provided is empty, a new shortuuid is generated.
139	// If provided is non-empty, it is validated against base.UIDMatcher.
140	func ValidateAndGenerateUID(provided string) (string, error) {
141		uid := strings.TrimSpace(provided)
142		if uid == "" {
143			return shortuuid.New(), nil
144		}
145		if !base.UIDMatcher.MatchString(uid) {
146			return "", status.Errorf(codes.InvalidArgument, "invalid ID format: must be 1-36 characters, alphanumeric and hyphens only, cannot start or end with hyphen")
147		}
148		return uid, nil
149	}
