28	export function getEndpointSummary(url: string): string {
29	  if (!url) {
30	    return "";
31	  }
32	
33	  try {
34	    const parsed = new URL(url);
35	    const path = parsed.pathname === "/" ? "" : parsed.pathname.replace(/\/$/, "");
36	    return `${parsed.host}${path}`;
37	  } catch {
38	    return url.replace(/^https?:\/\//, "").replace(/\/$/, "");
39	  }
40	}
