42	export function getFieldMappingSummary(mapping: FieldMapping | undefined, t: Translate): string {
43	  if (!mapping?.identifier) {
44	    return t("setting.sso.mapping-none");
45	  }
46	
47	  const parts = [`${t("setting.sso.mapping-identifier-short")}=${mapping.identifier}`];
48	  if (mapping.displayName) {
49	    parts.push(`${t("setting.sso.mapping-display-name-short")}=${mapping.displayName}`);
50	  }
51	  if (mapping.email) {
52	    parts.push(`${t("setting.sso.mapping-email-short")}=${mapping.email}`);
53	  }
54	  if (mapping.avatarUrl) {
55	    parts.push(`${t("setting.sso.mapping-avatar-short")}=${mapping.avatarUrl}`);
56	  }
57	  return parts.join(" · ");
58	}
