67	export function getOAuth2SummaryItems(provider: IdentityProvider, t: Translate): SummaryItem[] {
68	  const oauth2Config = provider.config?.config.case === "oauth2Config" ? provider.config.config.value : undefined;
69	  if (!oauth2Config) {
