76	export function buildOAuth2SummaryItems(oauth2Config: OAuth2Config, identifierFilter: string, t: Translate): SummaryItem[] {
77	  const endpointSummaries = [oauth2Config.authUrl, oauth2Config.tokenUrl, oauth2Config.userInfoUrl].map(getEndpointSummary).filter(Boolean);
78	  const uniqueEndpointSummaries = [...new Set(endpointSummaries)];
79	
80	  return [
81	    {
82	      key: "endpoints",
83	      label: t("setting.sso.endpoints"),
84	      value: uniqueEndpointSummaries.join(" · "),
85	      tooltip: [oauth2Config.authUrl, oauth2Config.tokenUrl, oauth2Config.userInfoUrl].filter(Boolean).join("\n"),
86	    },
87	    {
88	      key: "mapping",
89	      label: t("setting.sso.mapping"),
90	      value: getFieldMappingSummary(oauth2Config.fieldMapping, t),
91	      tooltip: oauth2Config.fieldMapping ? getFieldMappingSummary(oauth2Config.fieldMapping, t) : undefined,
92	    },
93	    {
94	      key: "scopes",
95	      label: t("setting.sso.scopes"),
96	      value:
97	        oauth2Config.scopes.length === 1
98	          ? t("setting.sso.scope-count_one", { count: oauth2Config.scopes.length })
99	          : t("setting.sso.scope-count_other", { count: oauth2Config.scopes.length }),
100	      tooltip: oauth2Config.scopes.length > 0 ? oauth2Config.scopes.join("\n") : undefined,
101	    },
102	    ...(identifierFilter
103	      ? [
104	          {
105	            key: "filter",
106	            label: t("setting.sso.identifier-filter"),
107	            value: getIdentifierFilterSummary(identifierFilter, t),
108	            tooltip: identifierFilter,
109	          },
110	        ]
111	      : []),
112	  ].filter((item) => item.value);
113	}
114	
115	function truncateMiddle(value: string, maxLength: number): string {
116	  if (value.length <= maxLength) {
117	    return value;
118	  }
119	
120	  const prefixLength = Math.ceil((maxLength - 1) / 2);
121	  const suffixLength = Math.floor((maxLength - 1) / 2);
122	  return `${value.slice(0, prefixLength)}…${value.slice(-suffixLength)}`;
123	}
